function breadcrumbs(page) {
  if (!page.slug) return [];
  const bits = page.slug.split('/');
  const crumbs = [{name:'Home', url:`${base}/`}];
  if (bits.length > 1) crumbs.push({name:'Resources', url:`${base}/resources/`});
  crumbs.push({name: page.h1, url:`${base}/${page.slug}/`});
  return crumbs;
}

function schema(page, canonical) {
  const graph = [
    {'@type':'Organization','@id':orgId,name:'Sri Bharathi',url:`${base}/`,logo:{'@type':'ImageObject',url:`${base}/assets/images/sri-bharathi-logo.png`},email:'info@sribharathi.com',telephone:'+91-94202-20324',subOrganization:[
      {'@type':'Organization',name:'Sri Bharathi Filtration Division',url:'https://filter.sribharathi.com/'},
      {'@type':'Organization',name:'Sri Bharathi Tech',url:'https://tech.sribharathi.com/'},
      {'@type':'Organization',name:'Sri Bharathi Chemicals',url:'https://chemical.sribharathi.com/'}]},
    {'@type':'WebSite','@id':siteId,url:`${base}/`,name:'Sri Bharathi',publisher:{'@id':orgId},inLanguage:'en-IN'}
  ];
  const crumbs = breadcrumbs(page);
  let type = page.pageType || (page.slug === 'about' ? 'AboutPage' : 'WebPage');
  const entity = {'@type':type,'@id':`${canonical}#webpage`,url:canonical,name:page.title,description:page.description,isPartOf:{'@id':siteId},about:{'@id':orgId},inLanguage:'en-IN'};
  if (type === 'Article') Object.assign(entity,{headline:page.h1,datePublished:page.datePublished,dateModified:page.datePublished,author:{'@id':orgId},publisher:{'@id':orgId},mainEntityOfPage:{'@id':`${canonical}#webpage`}});
  if (crumbs.length) entity.breadcrumb = {'@id':`${canonical}#breadcrumb`};
  graph.push(entity);
  if (crumbs.length) graph.push({'@type':'BreadcrumbList','@id':`${canonical}#breadcrumb`,itemListElement:crumbs.map((c,i)=>({'@type':'ListItem',position:i+1,name:c.name,item:c.url}))});
  return JSON.stringify({'@context':'https://schema.org','@graph':graph});
}

function header(page) {
  const current = `/${page.slug.split('/')[0]}/`;
  return `<header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Sri Bharathi home"><img src="/assets/images/sri-bharathi-logo.png" width="220" height="103" alt="Sri Bharathi" decoding="async"></a><nav class="desktop-nav" aria-label="Primary">${nav.map(([n,u])=>`<a href="${u}"${current===u?' aria-current="page"':''}>${n}</a>`).join('')}</nav><button class="menu-button" type="button" aria-expanded="false" aria-controls="mobile-nav"><span class="sr-only">Open navigation</span><i></i><i></i><i></i></button></div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile" hidden>${nav.map(([n,u])=>`<a href="${u}"${current===u?' aria-current="page"':''}>${n}</a>`).join('')}</nav></header>`;
}

function footer() { return `<footer class="site-footer"><div class="wrap footer-grid"><div><img src="/assets/images/sri-bharathi-logo.png" width="190" height="89" alt="Sri Bharathi" loading="lazy" decoding="async"><p>Corporate home for industrial filtration, enterprise technology and chemicals.</p></div><div><h2>Company</h2><a href="/about/">About</a><a href="/innovation/">Innovation</a><a href="/quality/">Quality</a><a href="/contact/">Contact</a></div><div><h2>Businesses</h2><a href="/filtration/">Industrial filtration</a><a href="/technology/">Technology</a><a href="/chemicals/">Chemicals</a></div><div><h2>Specialist sites</h2><a href="https://filter.sribharathi.com/">Filtration division ↗</a><a href="https://tech.sribharathi.com/">Technology division ↗</a><a href="https://chemical.sribharathi.com/">Chemicals division ↗</a></div></div><div class="wrap footer-base"><p>© ${new Date().getFullYear()} Sri Bharathi. All rights reserved.</p><a href="mailto:info@sribharathi.com">info@sribharathi.com</a></div></footer>`; }

function render(page) {
  const canonical = page.slug ? `${base}/${page.slug}/` : `${base}/`;
  const crumbs = breadcrumbs(page);
  const crumbHtml = crumbs.length ? `<nav class="breadcrumbs wrap" aria-label="Breadcrumb"><ol>${crumbs.map((c,i)=>`<li>${i===crumbs.length-1?`<span aria-current="page">${c.name}</span>`:`<a href="${c.url.replace(base,'')||'/'}">${c.name}</a>`}</li>`).join('')}</ol></nav>` : '';
  return `<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${page.title}</title><meta name="description" content="${page.description}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${canonical}"><meta property="og:type" content="${page.pageType==='Article'?'article':'website'}"><meta property="og:site_name" content="Sri Bharathi"><meta property="og:title" content="${page.title}"><meta property="og:description" content="${page.description}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${base}/assets/images/sri-bharathi-logo.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${page.title}"><meta name="twitter:description" content="${page.description}"><meta name="theme-color" content="#061e2d"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" href="/assets/favicon-32.png" type="image/png" sizes="32x32"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png" sizes="180x180"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${schema(page,canonical)}</script><script src="/assets/site.js" defer></script></head><body>${header(page)}${crumbHtml}<main id="main"><section class="hero${page.slug?' inner-hero':''}"><div class="wrap hero-grid"><div><p class="eyebrow">${page.kicker}</p><h1>${page.h1}</h1>${page.statement?`<p class="hero-statement">${page.statement}</p>`:''}<p class="lede">${page.intro}</p>${!page.slug?'<div class="hero-actions"><a class="button" href="/businesses/">Explore our businesses</a><a class="text-link" href="/contact/">Contact Sri Bharathi</a></div>':''}</div><div class="hero-mark" aria-hidden="true"><span>F</span><span>T</span><span>C</span><i></i></div></div></section>${page.body}<section class="cta"><div class="wrap split"><div><p class="eyebrow">Start in the right place</p><h2>Bring the problem, process or system context.</h2></div><div><p>We’ll help route your enquiry to filtration, technology, chemicals or the corporate team.</p><a class="button light" href="/contact/">Contact Sri Bharathi</a></div></div></section></main>${footer()}</body></html>`;
}

